{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Sodium saccharin, a cyclic sulfonamide structurally related to the query's sulfonamide/isoindolinone system, had an extent of absorption of 0.84±0.08 versus i.v. in fasted volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Tolfenamic acid, a chlorinated aromatic carboxylic acid, showed absolute oral bioavailability of 61.6% versus IV in healthy volunteers, supporting F well above the 20% threshold for halogenated aromatic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Meclofenamate, a chlorinated fenamate NSAID, had human oral bioavailability above 85%, providing affirmative evidence that polar chlorinated aromatic compounds can be highly bioavailable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "2,4-D, a chlorinated phenoxy acid, showed rapid and complete oral bioavailability in humans, supporting high absorption for small chlorinated aromatic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Meperidine absolute oral bioavailability ranged from 47% to 73% versus IV in healthy men, demonstrating that even compounds with substantial first-pass metabolism remain above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "TCDD, a highly chlorinated aromatic compound, had 80–90% oral bioavailability in animals and humans in lipophilic vehicles, supporting high F for chlorinated aromatic structures.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is predicted to have high absolute oral bioavailability (F >= 20%). Multiple high-transfer analogues with relevant sulfonamide, chlorinated aromatic, and polar features show oral F values of approximately 45–100%, and no affirmative evidence indicates F < 20%.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule itself was supplied.",
    "Some records report unspecified bioavailability type rather than strictly absolute oral bioavailability.",
    "First-pass metabolism and transporter effects specific to the sulfonamide-isoindolinone scaffold are not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

